class Membrane < SimpleDelegator
  def initialize(target, policy)
    super(target); @policy, @revoked, @wrappers = policy, false, {}.compare_by_identity
  end
  def wrap(obj)
    return obj unless obj.is_a?(Capability)             # only capabilities
    @wrappers[obj] ||= Membrane.new(obj, @policy)       # one wrapper per raw
  end
  def method_missing(name, *args, &blk)
    raise 'revoked' if @revoked
    wrap(__getobj__.public_send(name, *args.map { |a| wrap(a) }, &blk))
  end
end

