class Membrane < BasicObject
  def initialize(target, policy)
    @target, @policy, @revoked = target, policy, false
    @wrappers = {}.compare_by_identity
  end

  def method_missing(name, *args, &blk)
    ::Kernel.raise 'revoked' if @revoked
    wrap(@target.public_send(name, *args.map { |a| wrap(a) }, &blk))
  end

  def ==(other) = @target == other          # identity stays with the target
end
